<?php
class CalendarController extends Controller {
    public function index(): void {Auth::requireLogin();$uid=Auth::user()['id'];$month=$_GET['month']??date('Y-m');if(!preg_match('/^\d{4}-\d{2}$/',$month))$month=date('Y-m');$from=$month.'-01';$to=date('Y-m-t',strtotime($from));$this->render('calendar/index',['month'=>$month,'transactions'=>Transaction::calendar($uid,$from,$to),'reminders'=>Reminder::all($uid),'peaks'=>Transaction::peakDays($uid),'csrf'=>$this->csrf()]);}
    public function reminderSave(): void {Auth::requireLogin();$this->verifyCsrf();Reminder::create(Auth::user()['id'],['title'=>trim($_POST['title']),'event_date'=>$_POST['event_date'],'amount'=>(float)($_POST['amount']??0),'kind'=>$_POST['kind'],'notes'=>trim($_POST['notes']??'')]);$this->flash('success','Recordatorio creado.');$this->redirect('index.php?url=calendar');}
    public function reminderEdit(): void {Auth::requireLogin();$uid=Auth::user()['id'];$id=(int)($_GET['id']??$_POST['id']??0); if($_SERVER['REQUEST_METHOD']==='POST'){ $this->verifyCsrf(); Reminder::update($id,$uid,['title'=>trim($_POST['title']),'event_date'=>$_POST['event_date'],'amount'=>(float)($_POST['amount']??0),'kind'=>$_POST['kind'],'notes'=>trim($_POST['notes']??'')]); $this->flash('success','Recordatorio actualizado.'); $this->redirect('index.php?url=calendar'); } $st=Database::get()->prepare('SELECT * FROM reminders WHERE id=? AND user_id=?');$st->execute([$id,$uid]);$rem=$st->fetch();if(!$rem){$this->flash('error','Recordatorio no encontrado.');$this->redirect('index.php?url=calendar');}$this->render('calendar/edit_reminder',['rem'=>$rem,'csrf'=>$this->csrf()]);}
    public function reminderDelete(): void {Auth::requireLogin();$this->verifyCsrf();Reminder::delete((int)$_POST['id'],Auth::user()['id']);$this->flash('success','Recordatorio eliminado.');$this->redirect('index.php?url=calendar');}
}
